//! ffprobe output recorded from files generated by ffmpeg 9.0.2 (`testsrc2`, `sine`), parsed into
//! the domain's media info.

#![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]

use std::path::Path;

use se_domain::{AssetKind, Flicks, FrameRate, MediaInfo};
use se_media::parse_probe_output;

fn parse(name: &str) -> (AssetKind, MediaInfo) {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/ffprobe")
        .join(format!("{name}.json"));
    parse_probe_output(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn h264_with_aac() {
    let (kind, info) = parse("h264");
    assert_eq!(kind, AssetKind::Video);
    assert_eq!(info.duration, Flicks::from_seconds_f64(3.0).ok());
    let video = info.video_stream.unwrap();
    assert_eq!(video.codec, "h264");
    assert_eq!(video.profile.as_deref(), Some("High"));
    assert_eq!(video.codec_tag.as_deref(), Some("avc1"));
    assert_eq!((video.width, video.height), (1280, 720));
    assert_eq!(video.frame_rate, Some(FrameRate::FPS_30));
    assert_eq!(video.bit_depth, Some(8));
    assert_eq!(video.chroma_subsampling.as_deref(), Some("4:2:0"));
    assert!(video.level.is_some());
    let audio = &info.audio_streams[0];
    assert_eq!(
        (audio.codec.as_str(), audio.profile.as_deref()),
        ("aac", Some("LC"))
    );
    assert_eq!(audio.sample_rate, 48_000);
}

#[test]
fn hevc_main_10_rotated_for_display() {
    let (kind, info) = parse("hevc10");
    assert_eq!(kind, AssetKind::Video);
    let video = info.video_stream.unwrap();
    assert_eq!(video.codec, "hevc");
    assert_eq!(video.profile.as_deref(), Some("Main 10"));
    assert_eq!(video.codec_tag.as_deref(), Some("hvc1"));
    assert_eq!(video.level, Some(120));
    assert_eq!(video.bit_depth, Some(10));
    assert_eq!(video.pixel_format.as_deref(), Some("yuv420p10le"));
    assert_eq!(video.frame_rate, Some(FrameRate::FPS_29_97));
    // The display matrix says 90° counter-clockwise, i.e. 270° clockwise.
    assert_eq!(video.rotation, 270);
}

#[test]
fn prores_422_with_pcm_sound() {
    let (kind, info) = parse("prores");
    assert_eq!(kind, AssetKind::Video);
    let video = info.video_stream.unwrap();
    assert_eq!(video.codec, "prores");
    assert_eq!(video.bit_depth, Some(10));
    assert_eq!(video.chroma_subsampling.as_deref(), Some("4:2:2"));
    assert_eq!(video.frame_rate, Some(FrameRate::FPS_25));
    assert_eq!(info.audio_streams[0].codec, "pcm_s24le");
}

#[test]
fn sound_only() {
    let (kind, info) = parse("audio");
    assert_eq!(kind, AssetKind::Audio);
    assert_eq!(info.video_stream, None);
    assert_eq!(info.audio_streams[0].channels, 2);
    assert_eq!(info.audio_streams[0].sample_rate, 44_100);
    assert_eq!(info.duration, Flicks::from_seconds_f64(3.0).ok());
}

#[test]
fn still_image() {
    let (kind, info) = parse("image");
    assert_eq!(kind, AssetKind::Image);
    assert_eq!(info.duration, None);
    assert_eq!(info.container, "png_pipe");
    let picture = info.video_stream.unwrap();
    assert_eq!((picture.width, picture.height), (640, 480));
    assert_eq!(picture.level, None);
    assert_eq!(picture.codec_tag, None);
}
